import sys; sys.path.insert(0, sys.argv[1]); from batch_lib import write_batch; from eintenn_routes import ROUTES
# (id, name, kind, x, y, roots, description, subs, links, person, activity)
P=[
('salters_gate',"The Salters' Gate",'site',72,65,['kess_market','kess_harbor'],"The gate between the Salzmarkt and the harbour, where every salt cart is counted through. The arch is white to head height.",
 [('arch','The Arch','A low arch with a tally-board nailed inside it.'),('tollhouse','The Toll-House','One room, one stove, one very large ledger.')],['kess_market','kess_harbor'],
 ('jost','Jost Marsh',"Toll-Clerk of the Salters' Gate",'a young man counting carts aloud without moving his lips',"“Forty-one,” he says, to nobody. Then, to you: “Jost Marsh. Do not speak to me while a cart is under the arch.”","Jost knows which carters water their salt, and charges them by the wet weight.","“Salt goes out, silver comes in,” Jost says. “I am the hinge.”",'arch','tollhouse'),
 ('count_carts','Count the carts through','A notch for each cart, and a second for each that rides too low.','arch',6,18,2,'skill_numbers',None)),
('netmenders_strand',"Netmenders' Strand",'site',80,74,['kess_harbor'],"A shingle beach east of the harbour where the nets are spread and mended. It smells of tar and yesterday.",
 [('racks','The Drying Racks','Nets hung like brown sails.'),('shingle','The Shingle','Boats drawn up and women with needles.')],['kess_harbor'],
 ('wiebke','Wiebke Tarn','Netmender of the Strand','a woman with a bone needle in her teeth and a net over her knees',"She speaks round the needle. “Wiebke Tarn. Hold that end. No, the other end.”","Wiebke can tell which boat a net came off by the knots.","“A fish only needs one hole,” Wiebke says. “I need to find all of them.”",'shingle','racks'),
 ('mend_nets','Mend nets','Find the hole, knot it shut, find the next.','shingle',7,17,2,'skill_fishing',None)),
('coopers_yard',"The Coopers' Yard",'site',73,56,['kess_market'],"A yard of barrel-makers north of the Salzmarkt. Salt, herring and ale all leave Kesselhaven in their work.",
 [('sheds','The Stave Sheds','Oak staves stacked to dry, every one numbered.'),('fire','The Hooping Fire','A ring of fire and men walking round it with hammers.')],['kess_market','kess_fondaco'],
 ('anselm','Anselm Hoop','Cooper of the Yard','a thick-armed man knocking a hoop down with a mallet',"He finishes the hoop first. “Anselm Hoop. And yes, that is the name, and no, I did not choose the trade to fit it.”","Anselm says a good barrel is tight without glue or nails, and so is a good guild.","“Everything in this town travels in my work,” Anselm says. “Nobody looks at the barrel.”",'fire','sheds'),
 ('shave_staves','Shave staves','Drawknife along the grain, until the curve is right by eye.','sheds',7,16,2,'skill_woodwork',None)),
('eelwater','Eelwater','village',60,72,['kess_undercroft','kess_harbor'],"A fen village west of the harbour, built on its own smoke. The eels are caught at night and hung over alder fires by day.",
 [('smokehouses','The Smokehouses','Black sheds that leak blue smoke.'),('dykes','The Dykes','Narrow water between reeds, with a punt in each.')],['kess_undercroft','aschau'],
 ('frauke','Frauke Fenn','Eel-Smoker of Eelwater','a woman with smoke-red eyes and a string of eels over her shoulder',"“Shut the door,” she says. “The smoke is the money.” Then: “Frauke Fenn. You get used to it.”","Frauke sells half her catch in the market and the other half, she says, to people who do not use the market.","“Alder, not oak,” Frauke says. “Oak is for people who do not like eels.”",'smokehouses','dykes'),
 ('hang_eels','Hang the eels to smoke','A hook through each, a pole of twenty, and into the dark.','smokehouses',8,16,2,'skill_cookery',None)),
('inkwell_row','Inkwell Row','site',60,57,['collegium','kess_market'],"A street of booksellers, copyists and cheap lodgings between the Collegium and the town. Students owe money at every door.",
 [('stalls','The Bookstalls','Trestles of second-hand learning.'),('garrets','The Garrets','Rooms let by the term, stairs by the dozen.')],['collegium','kess_market'],
 ('konrad','Konrad Vellum','Bookseller of the Row','a dusty man reading his own stock with a finger on the line',"He keeps his finger where it is. “Konrad Vellum. You may read standing up for nothing. Sitting down costs.”","Konrad buys the same books back from the same students every spring.","“A scholar sells his books in this order,” Konrad says. “Theology first. Then the rest.”",'stalls','garrets'),
 ('sort_books','Sort a crate of books','By subject, then by size, then by how much is missing.','stalls',9,18,2,'skill_letters',None)),
('starwatch_hill','Starwatch Hill','site',66,48,['collegium'],"A bare hill north of the Collegium with a ring of sighting stones on top. Students come up at night; sheep keep it by day.",
 [('stones','The Sighting Stones','Seven waist-high stones, each with a notch.'),('fold','The Sheepfold','A dry-stone fold on the lee side.')],['collegium','place_eintenn_falkenau'],
 ('lena','Lena Hale','Shepherd of Starwatch','a young woman with a crook, scratching numbers on a slate',"“They pay me to keep the sheep off the stones,” she says. “Lena Hale. I learned the rest by listening.”","Lena can name more stars than most of the students who climb the hill.","“The sheep do not care which way is north,” Lena says. “I do, now.”",'fold','stones'),
 ('keep_sheep','Keep the sheep off the stones','Walk the ring, whistle the dog, and count them twice.','fold',6,19,2,'skill_beastcraft',None)),
('panners_row',"Panners' Row",'village',84,80,['salzmoor'],"A row of low houses at the edge of the Salzmoor where the pan-workers live. Everything here is crusted white, the children included.",
 [('row','The Row','Twelve houses, one pump, no trees.'),('store','The Salt Store','A barn of grey salt waiting for the carts.')],['salzmoor','kess_harbor'],
 ('ebbo','Ebbo Rake','Salt-Panner of the Row','a man with cracked hands and a wide wooden rake',"He shows you his palms. “Ebbo Rake. That is what salt does. Still better than the mines.”","Ebbo says the moor gives salt to anyone and takes a cart, a horse or a man every few years in exchange.","“Wind and sun do the work,” Ebbo says. “I only tidy up after them.”",'store','row'),
 ('rake_salt','Rake the salt','Long strokes, into ridges, and let it drain.','store',6,15,2,'skill_athletics',None)),
('mud_chapel','The Mud Chapel','site',90,78,['salzmoor'],"A small chapel on stilts above the tidal flats, kept for those the moor has taken. Its bell rings in fog.",
 [('nave','The Nave','Six benches and a wall of names cut in driftwood.'),('belfry','The Fog Bell','A bell on a frame, with a long wet rope.')],['salzmoor','panners_row'],
 ('ansgar','Brother Ansgar','Keeper of the Mud Chapel','a monk with his habit tucked up and mud to the knee',"“Boots off,” he says. “The floor is the cleanest thing for a mile.” Then: “Brother Ansgar. I ring the bell and I cut the names.”","Ansgar has pulled eleven people off the flats by following his own bell back.","“The tide keeps no hours you can trust,” Ansgar says. “So I keep mine.”",'nave','belfry'),
 ('ring_fog_bell','Ring the fog bell','Three pulls, a count of sixty, three pulls.','belfry',5,22,1,'skill_devotion',None)),
('haverford','Haverford','village',74,78,['kess_harbor','salzmoor'],"A farm village at the ford on the way to the Salzmoor. Its oats feed half the cart-horses of Kesselhaven.",
 [('ford','The Ford','Wide, shallow and full of carts.'),('oatfields','The Oatfields','Pale fields to the edge of the marsh.')],['kess_harbor','panners_row'],
 ('greta','Greta Stile','Farmer of Haverford','a brisk woman with a sack of oats on one hip',"“If you are going to the moor, you are going the wrong way,” she says. “Greta Stile. Everyone asks.”","Greta charges carters for oats and for pulling them out of the ford, and says the second pays better.","“A horse works on oats,” Greta says. “So this town works on me.”",'oatfields','ford'),
 ('cut_oats','Cut oats','Sickle low, bind the sheaf, stand it up.','oatfields',6,17,3,'skill_husbandry',None)),
('long_reach','The Long Reach','site',80,42,['wp_ferry','kess_fondaco'],"A straight mile of river where the barges are hauled upstream by men on a towpath. There is a hut, a fire and a great deal of rope.",
 [('towpath','The Towpath','A worn path with a groove where the rope runs.'),('hut','The Haulers’ Hut','A fire that never goes out and boots drying round it.')],['wp_ferry','kess_fondaco'],
 ('dierk','Dierk Tow','Hauler of the Reach','a broad man leaning into a rope as if into a wind',"He does not stop. “Walk with me if you want to talk. Dierk Tow. The barge will not wait.”","Dierk has walked from the sea to the ferry more times than he can count, and never once back by water.","“Downstream is free,” Dierk says. “Upstream is me.”",'towpath','hut'),
 ('haul_barge','Haul a barge','Rope over the shoulder, lean, and walk.','towpath',6,17,3,'skill_athletics',None)),
('osterau','Osterau','village',72,38,['wp_ferry','collegium'],"A flax village in the river meadows. In summer the fields are blue for a week; in autumn the whole place stinks of retting.",
 [('retting','The Retting Ponds','Flax rotting under stones, on purpose.'),('green','The Scutching Green','Women beating flax on boards.')],['long_reach','starwatch_hill'],
 ('gesche','Gesche Retter','Flax-Wife of Osterau','a tall woman beating a bundle of flax as if it had insulted her',"She gives it one more blow. “Gesche Retter. You will stop noticing the smell in a day. Or a year.”","Gesche sells her best line to the Fondaco and says they pay in promises and thin silver.","“Linen is patience you can wear,” Gesche says.",'green','retting'),
 ('scutch_flax','Scutch flax','Beat it, shake it, beat it again, until the straw falls out.','green',7,17,2,'skill_clothwork',None)),
('lindenau','Lindenau','village',62,34,['tennfels','silberhalde'],"A village round a great lime tree, known for its horse fair. Half the cart-horses and a few of the destriers of Eintenn were first sold under that tree.",
 [('green','The Lime Green','A tree four men cannot span, and a ring of posts.'),('paddocks','The Paddocks','Long fields with good fences.')],['place_eintenn_falkenau','osterau','silberhalde'],
 ('rupp','Rupp Halter','Horse-Coper of Lindenau','a bow-legged man looking at a horse’s teeth',"He lets the lip go. “Seven, not five. Rupp Halter. Never buy a horse from a man in a hurry.”","Rupp remembers every horse he has sold and what became of it.","“The knights want height,” Rupp says. “The carters want sense. I breed for the carters.”",'paddocks','green'),
 ('walk_horses','Walk the horses','Round the ring at a walk, so the buyers can see them move.','paddocks',7,16,2,'skill_beastcraft',None)),
('slag_heaps','The Slag Heaps','site',45,28,['silberhalde'],"Grey hills of waste below Silberhalde. Pickers go over them for the ore the smelters missed.",
 [('heaps','The Heaps','Loose grey slopes that slide underfoot.'),('washing','The Washing Trough','A trough and a sieve, and cold hands.')],['silberhalde','place_eintenn_black_quarry'],
 ('detlef','Detlef Clink','Picker of the Heaps','a young man with a hammer, cracking stones and looking inside',"He cracks one more. “Nothing. Detlef Clink. One in fifty has colour in it.”","Detlef sells what he finds back to the smelter that threw it away.","“They are in a hurry up there,” Detlef says. “I am not.”",'heaps','washing'),
 ('pick_slag','Pick over the slag','Crack it, look, throw it behind you. Keep the ones that shine.','heaps',7,17,2,'skill_mining',12)),
('stollenwick','Stollenwick','village',38,20,['silberhalde'],"A miners’ village on the slope above the workings. The men go down before light and come up after it, so the village belongs to the women.",
 [('lane','The Steep Lane','One lane, cobbled, with a rope to hold in winter.'),('washhouse','The Wash-House','Where the grey comes out of the clothes, mostly.')],['silberhalde','place_eintenn_verderers_lodge'],
 ('marta','Marta Pick','Washerwoman of Stollenwick','a woman wringing a grey shirt over a grey trough',"“Do not lean on that wall, it is drying,” she says. “Marta Pick. Three sons below. I count them up every night.”","Marta knows which seam is being worked by the colour of the dirt that comes home.","“Silver comes out white,” Marta says. “Everything else comes out grey.”",'washhouse','lane'),
 ('wash_greys','Wash the greys','Soak, beat, rinse. The water runs like slate.','washhouse',7,15,2,'skill_clothwork',None)),
('wolf_pits','The Wolf Pits','site',34,28,['grauwald'],"Old pits at the edge of the Grauwald, dug for wolves in a hard winter and kept ever since. A warden walks them at dawn.",
 [('pits','The Pits','Deep, stake-floored and roofed with brush.'),('bothy','The Warden’s Bothy','A hut with pelts on the wall.')],['grauwald','place_eintenn_verderers_lodge'],
 ('gunther','Gunther Snare','Wolf-Warden of the Pits','a quiet man with a spear and a limp',"“Walk where I walk,” he says. “Exactly.” When you are across: “Gunther Snare. That is how I got the limp.”","Gunther has taken four wolves in nine years, and says the pits mostly catch drunkards.","“The wolves know where the pits are,” Gunther says. “That is the point.”",'pits','bothy'),
 ('lay_brush','Lay fresh brush','Light sticks, then leaves, then walk away backwards.','pits',6,12,1,'skill_woodcraft',None)),
('high_byre','The High Byre','site',26,18,['hohenkamm'],"A summer byre below the Hohenkamm where the cattle are driven up at the thaw. The cheese comes down in autumn, and the herders with it.",
 [('byre','The Byre','A long stone byre with a turf roof.'),('pasture','The Summer Pasture','Short grass, bells and a great deal of sky.')],['hohenkamm','greenwife_grove'],
 ('irmel','Irmel Horn','Herdswoman of the High Byre','a sunburnt woman with a cow-horn slung on a cord',"She blows one note on the horn and every cow looks up. “Irmel Horn. That is all the magic I have.”","Irmel has not been below the tree-line between thaw and frost since she was twelve.","“Up here the weather tells you first,” Irmel says. “Down there you find out.”",'pasture','byre'),
 ('turn_cheeses','Turn the cheeses','Every wheel, every day, and a rub of salt.','byre',6,18,1,'skill_cookery',None)),
('pilgrim_stair','The Pilgrim Stair','site',55,12,['threshold_sanctum','vaelis_ruins'],"A stair of worn steps cut into the hillside on the way north. Someone has swept it every morning for longer than anyone remembers.",
 [('steps','The Steps','Three hundred and some. Nobody agrees on the count.'),('rest','The Half-Way Rest','A stone bench and a spring.')],['threshold_sanctum','vaelis_ruins'],
 ('odila','Odila Staff','Sweeper of the Stair','an old woman with a birch broom, working downward',"“Mind the wet ones,” she says. “Odila Staff. My mother swept it. Do not ask me why. It wants sweeping.”","Odila says you can tell a pilgrim from a scholar by which of them looks at the steps.","“Going up, they pray,” Odila says. “Coming down, they are hungry.”",'steps','rest'),
 ('sweep_stair','Sweep the stair','Top to bottom, a step at a time, leaves over the edge.','steps',6,11,2,'skill_wayfaring',None)),
('kelterwick','Kelterwick','village',52,72,['aschau'],"A village east of Aschau built round one great wine-press. At vintage the whole street runs purple.",
 [('press','The Great Press','A beam the length of a barn, and a screw taller than a man.'),('cellars','The Cool Cellars','Rows of casks chalked with the year.')],['aschau','place_eintenn_vintners_halt','eelwater'],
 ('lutz','Lutz Tread','Pressman of Kelterwick','a man with purple feet and a contented look',"He looks down at his feet with you. “Lutz Tread. They go white again by spring.”","Lutz can tell the slope a grape grew on by treading it.","“The press does the work,” Lutz says. “The feet do the first kindness.”",'press','cellars'),
 ('turn_press','Turn the press','Four to the beam, and round, and listen for the run.','press',7,18,2,'skill_cookery',None)),
('appleford','Appleford','village',36,80,['pomerell'],"A ford and a few houses on the cart-road to Pomerell. In autumn the cider carts queue to the bend.",
 [('ford','The Ford','Gravel-bottomed, and sweet-smelling in October.'),('yard','The Carters’ Yard','A trough, a smith’s lean-to and a bench.')],['pomerell','place_eintenn_pomerell_grange','place_eintenn_hollin_cross'],
 ('sanne','Sanne Withy','Ford-Keeper of Appleford','a young woman with a pole, standing in the stream to her knees',"“Left of the white stone,” she calls. “Left!” Then, wading out: “Sanne Withy. They never listen the first time.”","Sanne has fished nine barrels and one abbot out of the ford.","“The river is polite in summer,” Sanne says. “Do not trust it.”",'ford','yard'),
 ('guide_carts','Guide carts over the ford','Stand at the white stone and point. Shout if you must.','ford',6,18,2,'skill_wayfaring',None)),
('bee_garth','The Bee Garth','site',24,80,['pomerell'],"The abbey’s walled bee yard, west of the orchards. Forty straw skeps stand in niches in the wall.",
 [('niches','The Bee Wall','A south wall of niches, each with a skep.'),('honeyhouse','The Honey-House','Crocks, cloths and a sticky floor.')],['pomerell','place_eintenn_sallowfield'],
 ('emmeran','Brother Emmeran','Bee-Ward of the Garth','a monk walking slowly along a wall, talking under his breath',"He holds up a finger until he has finished the sentence. “I was telling them the news. Brother Emmeran. They like to know.”","Emmeran says the bees are told of every death at the abbey before the bell is rung.","“No orchard without them,” Emmeran says. “The abbot knows it, too.”",'niches','honeyhouse'),
 ('strain_honey','Strain the honey','Comb into the cloth, and let it take its time.','honeyhouse',8,16,1,'skill_husbandry',None)),
('greywater_weir','Greywater Weir','site',18,58,['ostwick','wisewoman_hut'],"A stone weir west of Ostwick with a fish-trap in its teeth. It is older than the village and nobody admits to building it.",
 [('weir','The Weir','A line of stones, and white water over them.'),('trap','The Fish-Trap','A wicker funnel as long as a boat.')],['place_eintenn_reedmere','place_eintenn_weirbeck_mill'],
 ('wendel','Wendel Sluice','Weir-Keeper of Greywater','a wet man lifting a wicker trap and peering in',"“Trout,” he says, pleased, and then sees you. “Wendel Sluice. The Duke gets every third one. I choose which.”","Wendel clears the weir after every storm and finds something odd in it each time.","“Water wants to go round,” Wendel says. “My whole trade is saying no.”",'trap','weir'),
 ('clear_weir','Clear the weir','Branches, weed and worse, hauled out by hand.','weir',6,16,2,'skill_fishing',None)),
]
write_batch(sys.argv[2] if len(sys.argv) > 2 else '.', 'eintenn', 'eintenn-02', P, "Eintenn, second batch: twenty-one small places round Kesselhaven, the river, the mines, the hills and the south.", routes=ROUTES)
